arguments.command:
cd /tmp/sv-8e2589fcbe24489d94e7a2318cc3ad80
# Use dynamic symbol table to find nearest symbols for each PC offset
for addr in 0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04; do
  echo -n "PC $addr -> "
  # Find the nearest symbol below this address
  nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | awk -v target="$addr" '
    BEGIN { best_name="??"; best_addr=0; target_dec=strtonum(target) }
    /^[0-9a-f]+ [TtWw]/ {
      addr_dec = strtonum("0x"$1)
      if (addr_dec <= target_dec && addr_dec > best_addr) {
        best_addr = addr_dec
        best_name = $3
      }
    }
    END { printf "%s+0x%x\n", best_name, target_dec - best_addr }
  '
done

